      "assessment": {
        "nobel_worthiness": "Squeezed light converts a fundamental quantum-optical resource into demonstrable sensitivity beyond conventional quantum noise limits.",
        "attribution": "Caves established the central quantum-measurement insight; Mavalvala and Schnabel made major experimental and interferometric contributions.",
        "maturity": "Routine use in major precision interferometers gives this work compelling experimental maturity.",
        "uncertainties": [
          "Attribution overlaps with the broader development of gravitational-wave interferometry and quantum optics."
        ]
      }
    },
